import{z as A,x as i,o as n,c as B,q as E,j as o,D as t,d as l,s,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"集合通信带宽模型","description":"","frontmatter":{"title":"集合通信带宽模型","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/collective-bandwidth-model.md","filePath":"llm/collective-bandwidth-model.md","lastUpdated":1791063341000}'),d={name:"llm/collective-bandwidth-model.md"};function h(c,a,m,b,u,C){const r=i("Mermaid");return n(),B("div",null,[a[2]||(a[2]=E('<h1 id="集合通信带宽模型" tabindex="-1">集合通信带宽模型 <a class="header-anchor" href="#集合通信带宽模型" aria-label="Permalink to &quot;集合通信带宽模型&quot;">​</a></h1><div class="epigraph"><p>集体时间不是「字节除以网卡标称」。先付启动延迟，再按算法效率付有效带宽；小消息活在 $\\alpha$ 区，大消息才摸到 $\\beta$ 区。</p><footer>—— Hockney 的 $\\alpha$–$\\beta$ 模型；集体算法分析见 Chan 等对 MPI 集合的经典整理</footer></div><p><a href="/llm/nccl-algorithms">上一课</a> 给出了库如何选环和树。本课把选择变成<strong>可算的时间</strong>：给定 \\(n\\) 字节、\\(N\\) 卡、链路延迟与带宽，All-Reduce / All-Gather / All-to-All 各该落在哪一段屋顶线上。缺口是定量，不是再列算法名。<a href="/llm/pretrain-comm">预训练通信</a> 写过 \\(T\\approx\\alpha+n\\beta\\)；本课把 \\(\\alpha\\)、\\(\\beta\\) 接到具体集体，并说明 busbw 与标称 Gb/s 差在哪。后课拓扑与拥塞处理 \\(\\beta\\) 不是常数的情况。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>网卡写 400 Gb/s，不等于 400 Gb/s 的梯度同步。集体算法有冗余与流水，有效带宽常写成 \\(\\frac{N-1}{N}\\) 一类因子；协议与 chunk 又吃掉一部分。更关键的是分区：消息小于某拐点时，时间几乎不随 \\(n\\) 降，因为全是 \\(\\alpha\\)——启动、同步、内核 launch、PCIe 门铃。张量并行的短 All-Reduce、MoE 小微批的 All-to-All，经常停在这个区。再买更胖的网卡，\\(\\beta\\) 变好，\\(\\alpha\\) 几乎不动，step 不变。</p><p>问题因此是：对每一种原语，写出 \\(T(n,N)\\) 的主导项，并用 <code>nccl-tests</code> 的 busbw 曲线把拐点测出来。没有拐点，并行网格是拍脑袋。</p><p><span class="marginnote">busbw 是 NCCL 测试里按算法理想因子反推的「总线带宽」，用来和链路规格比。algbw 是 \\(n/T\\)。两者都要看：algbw 接近应用，busbw 接近硬件是否吃满。</span></p><p><span class="marginnote">直觉类比：把通信想成寄快递——\\(\\alpha\\) 是下单、揽收、签收这些固定手续，寄一个信封也要走全套；\\(\\beta\\) 是每公斤运费。信封（小消息）贵在手续，家具（大梯度）贵在运费，所以小消息要靠「合并少寄几次」救，大消息要靠「换更宽的路」救。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>点对点：\\(T \\approx \\alpha + n\\beta\\)，其中 \\(\\beta=1/B\\)，\\(B\\) 为该路径有效带宽（NVLink 一档，IB/RoCE 另一档）。</p><p>Ring All-Reduce：约 \\(T \\approx 2(N-1)\\alpha + 2\\frac{N-1}{N}n\\beta\\)。前项随 \\(N\\) 涨，后项接近 \\(2n\\beta\\)。大 \\(n\\)、中等 \\(N\\) 时第二项主导，这是环「带宽最优」的含义。</p><p><span class="marginnote">数字实例：\\(N=8\\) 卡时效率因子 \\(\\frac{N-1}{N}=\\frac{7}{8}\\)，即环 All-Reduce 每卡至少要收发约两倍梯度体积（\\(2\\times\\frac{7}{8}n\\)）；若 \\(n=1\\) GB、有效带宽 \\(B=200\\) GB/s，数据项就是 \\(2\\times\\frac{7}{8}\\times 1/200 \\approx 8.8\\) ms——这就是大模型梯度同步的基本盘。</span></p><p>Tree All-Reduce：跳数 \\(O(\\log N)\\)，前项变成 \\(O(\\log N)\\,\\alpha\\)，数据项通常差于环（根附近不能把体积摊匀），除非层次化把跨节点 \\(n\\) 先除以每节点 GPU 数。</p><p>All-Gather / Reduce-Scatter：大约是 All-Reduce 数据项的一半，延迟项仍随算法的步数走。</p><p>All-to-All：数据项约 \\((N-1)m\\beta\\)（\\(m\\) 为每对净荷），延迟项依调度是 \\(O(N)\\) 或 \\(O(\\log N)\\)。没有 \\(\\frac{N-1}{N}\\) 那种「加完变少」。</p>',15)),(n(),o(p,null,{default:t(()=>[s(r,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20LR%0A%20%20N%5B%22%E6%B6%88%E6%81%AF%E5%A4%A7%E5%B0%8F%20n%22%5D%20--%3E%20CMP%7B%22%E7%9B%B8%E5%AF%B9%E6%8B%90%E7%82%B9%22%7D%0A%20%20CMP%20--%3E%7C%22n%20%E5%B0%8F%22%7C%20A%5B%22alpha%20%E4%B8%BB%E5%AF%BC%3A%20%E5%87%8F%E6%AC%A1%E6%95%B0%E6%88%96%E7%BC%A9%E7%BB%84%22%5D%0A%20%20CMP%20--%3E%7C%22n%20%E5%A4%A7%22%7C%20B%5B%22beta%20%E4%B8%BB%E5%AF%BC%3A%20%E7%9C%8B%E6%8B%93%E6%89%91%E4%B8%8E%E7%AE%97%E6%B3%95%E6%95%88%E7%8E%87%22%5D%0A%20%20B%20--%3E%20NV%5B%22NVLink%20%E5%9F%9F%22%5D%0A%20%20B%20--%3E%20NIC%5B%22%E7%BD%91%E5%8D%A1%20%2F%20Clos%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[l("工程上：对每个进程组（TP / DP / EP）用真实消息大小跑微基准，标出拐点。TP 组应落在 "),e("a",{href:"/llm/nvlink"},"NVLink"),l(" 的 \\(\\beta\\) 区或至少 \\(\\alpha\\) 可接受；DP 组允许跨节点，但要把 All-Reduce 与计算重叠，使暴露出来的 \\(T\\) 小于层计算。EP 组若 \\(m\\) 落在 \\(\\alpha\\) 区，先加微批或缩 EP 度，再升级网络。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[l("\\(\\alpha\\) 来自软件栈与同步：NCCL 内核启动、FIFO、跨节点 RDMA 握手、以及集体的全局同步波。多进程组并发时，\\(\\alpha\\) 会变差，因为门铃与完成队列互相干扰。\\(\\beta\\) 来自链路与争用：同一 NVLink 域里 TP 与另一组 All-Gather 抢注入，有效 \\(B\\) 下降。模型里的 \\(B\\) 必须是"),e("strong",null,"该 step 同时在飞的集体之和"),l("下的剩余，而不是空载规格。")],-1)),a[6]||(a[6]=e("p",null,"层次化改变的是代入公式的 \\(n\\) 与 \\(N\\)：节点内 \\(N_{\\mathrm{local}}\\)、\\(B_{\\mathrm{nvlink}}\\)；跨节点 \\(N_{\\mathrm{nodes}}\\)、\\(n_{\\mathrm{node}}=n/N_{\\mathrm{local}}\\)、\\(B_{\\mathrm{nic}}\\)。总时间是两段之和，不是用集群总卡数套一次环公式——那会严重高估跨节点环的 \\(\\alpha\\)。",-1)),(n(),o(p,null,{default:t(()=>[s(r,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20G%5B%22%E5%85%A8%E9%83%A8%20GPU%20%E6%A2%AF%E5%BA%A6%20n%22%5D%20--%3E%20S1%5B%22%E8%8A%82%E7%82%B9%E5%86%85%20Reduce-Scatter%3Cbr%2F%3E%E8%B5%B0%20NVLink%2C%20%E4%BD%93%E7%A7%AF%E5%90%84%E7%95%99%20n%2F8%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E8%B7%A8%E8%8A%82%E7%82%B9%20Reduce-Scatter%3Cbr%2F%3E%E5%8F%AA%E4%BC%A0%E8%8A%82%E7%82%B9%E5%86%85%E5%B7%B2%E5%BD%92%E7%BA%A6%E7%9A%84%20n%2F8%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E8%B7%A8%E8%8A%82%E7%82%B9%20All-Gather%3Cbr%2F%3E%E7%BB%93%E6%9E%9C%E5%9B%9E%E7%81%8C%E5%90%84%E8%8A%82%E7%82%B9%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E8%8A%82%E7%82%B9%E5%86%85%20All-Gather%3Cbr%2F%3ENVLink%20%E8%A1%A5%E5%85%A8%E6%9C%AC%E6%9C%BA%208%20%E4%BB%BD%22%5D%0A%20%20S4%20--%3E%20R%5B%22%E6%AF%8F%E5%BC%A0%E5%8D%A1%E9%83%BD%E6%9C%89%E5%AE%8C%E6%95%B4%E6%A2%AF%E5%BA%A6%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">通信 dtype 进入 \\(n\\)。BF16 梯度相对 FP32 减半；FP8 再减。数值协议必须在所有 DP 副本对齐，见预训练通信课。模型里改 \\(n\\) 之前，先确认这是配方允许的精度，不是网卡开关。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(\\alpha\\)–\\(\\beta\\) 忽略拥塞与丢包：它是空载或轻度负载的一阶模型。下一课起的轨拓扑与拥塞控制处理 \\(\\beta\\) 随时间变的部分。也不要把 GPU 核内归约时间漏掉：极小消息时，本地加与同步可能比链路更贵。</p><p>不要用峰值 FLOPS 去除通信时间来「证明」重叠成功。重叠成功的判据是：step 时间 ≈ 计算屋顶线，而不是通信公式的 \\(T\\) 单独变小。公式用来决定并行维画在哪张图上，用来解释为何加带宽救不了 TP。</p><p><span class="marginnote">常见误区：看到网卡标称 400 Gb/s 就以为 busbw 也能到 400。实际上协议头、chunk 切分、拥塞都要扣钱，busbw 能到标称的七八成已算健康；测出来只有一半时，先查是不是有别的进程组在同时通信，而不是急着换硬件。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>集体时间 = 延迟项 + 数据项；拐点以下加带宽无效。</li><li>环 All-Reduce 数据项约 \\(2\\frac{N-1}{N}n\\beta\\)；All-to-All 没有归约减体积。</li><li>层次化要分段套公式，禁止用总卡数套一次环。</li><li>用 nccl-tests 的 busbw 曲线标定每个进程组的拐点。</li><li>出处：Hockney \\(\\alpha\\)–\\(\\beta\\)；Chan 等对集合通信的算法分析；NCCL 测试指标。</li></ul>',7))])}const P=A(d,[["render",h]]);export{f as __pageData,P as default};
